		}
		return nil, problemDetails
	}

	// exist and not empty link: http:{ip:port}/api/.../?plmn-id=xxx
	plmnIDJson := values[0]
	plmnIDStruct = &models.PlmnId{}
	err := json.Unmarshal([]byte(plmnIDJson), plmnIDStruct)
